import{_ as c,C as i,o as l,c as n,ak as r,E as o,j as t,a}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"Sortable 排序","description":"","frontmatter":{},"headers":[],"relativePath":"components/sortable.md","filePath":"components/sortable.md","lastUpdated":1790408597000}'),s={name:"components/sortable.md"};function h(b,d,g,p,m,u){const e=i("XhDemo");return l(),n("div",null,[d[0]||(d[0]=r('<h1 id="sortable-排序" tabindex="-1">Sortable 排序 <a class="header-anchor" href="#sortable-排序" aria-label="Permalink to &quot;Sortable 排序&quot;">​</a></h1><p>通过拖拽或键盘重新排列内容。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/sortable" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/sortable.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/sortable" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/sortable" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/sortable.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>拖动任务调整顺序</p>',5)),o(e,{src:"sortable/01-basic"}),d[1]||(d[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;sortable&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong> · <code>item-drag-trigger</code> · <code>drop-indicator</code> · <code>live-region</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="水平排序" tabindex="-1">水平排序 <a class="header-anchor" href="#水平排序" aria-label="Permalink to &quot;水平排序&quot;">​</a></h3><p>调整标签顺序</p>',6)),o(e,{src:"sortable/02-horizontal"}),d[2]||(d[2]=t("h3",{id:"网格排序",tabindex:"-1"},[a("网格排序 "),t("a",{class:"header-anchor",href:"#网格排序","aria-label":'Permalink to "网格排序"'},"​")],-1)),d[3]||(d[3]=t("p",null,"在换行布局中排序",-1)),o(e,{src:"sortable/03-grid"}),d[4]||(d[4]=t("h3",{id:"禁用项目",tabindex:"-1"},[a("禁用项目 "),t("a",{class:"header-anchor",href:"#禁用项目","aria-label":'Permalink to "禁用项目"'},"​")],-1)),d[5]||(d[5]=t("p",null,"固定单个项目的位置",-1)),o(e,{src:"sortable/04-disabled"}),d[6]||(d[6]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>调整任务、标签页、收藏项或表格列的顺序。</li><li>需要保存用户定义的排列顺序。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>数据规则决定顺序时使用普通排序。</li><li>跨容器拖拽需要使用更完整的拖放方案。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持垂直、水平和换行网格排序。</li><li>拖动时实时显示让位和落点；放下后项目从松手处带着松手速度落进新位置。</li><li>支持边缘自动滚动。</li><li><code>sort</code> 事件返回重排后的 <code>ids</code>。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>可在项目中放置独立拖拽手柄。</li><li>可与<a href="./table">表格</a>组合为列排序面板。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>拖拽手柄放在项目的固定位置，与项目内的其他控件分开。</li><li>拖放结束后立刻持久化 <code>ids</code>，失败时回滚并提示。</li><li>项目高度保持一致，让位动画才能表达落点。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用整个项目作为手柄，项目内的按钮与链接将无法点击。</li><li>拖动中改变列表长度或过滤条件。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-sortable&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSortableDropIndicator</code> <code>XhSortableItem</code> <code>XhSortableItemDragTrigger</code> <code>XhSortableLiveRegion</code> <code>XhSortableRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSortable</code></td></tr><tr><td>状态机</td><td><code>sortableMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/sortable.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>ids</code></td><td><code>string[]</code></td><td>是</td><td>项的稳定标识，数组顺序即当前顺序。这是顺序的唯一真源。 DOM 中项的先后必须与它一致：几何按 DOM 测量，回调按它计算。</td></tr><tr><td><code>orientation</code></td><td><code>SortableAxis</code></td><td></td><td>排序沿哪根轴进行。换行网格使用 <code>both</code>。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>activationDistance</code></td><td><code>number</code></td><td></td><td>按下之后移动多远才视为开始拖动，默认 5px。提供 0 表示按下即拖动。</td></tr><tr><td><code>autoScroll</code></td><td><code>boolean</code></td><td></td><td>拖到容器边缘时自动滚动，默认开启。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;SortableTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onSort</code></td><td><code>(details: SortableSortDetails) =&gt; void</code></td><td></td><td>顺序变化意图。取消的一次不发出。</td></tr><tr><td><code>onDragStart</code></td><td><code>(details: SortableDragStartDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onDragEnd</code></td><td><code>(details: SortableDragEndDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>SortableSortDetails</code></td><td>顺序变化；detail 为 <code>{ from, to, id, ids }</code>，其中 ids 已重排</td></tr><tr><td><code>drag-start</code></td><td><code>SortableDragStartDetails</code></td><td>拾起；detail 为 <code>{ id, from, mode }</code></td></tr><tr><td><code>drag-end</code></td><td><code>SortableDragEndDetails</code></td><td>收尾（含取消）；detail 为 <code>{ id, from, to, mode, canceled }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSortableItem</code></td><td><code>default</code></td><td><code>SortableItemSlotProps</code></td><td></td></tr><tr><td><code>XhSortableItemDragTrigger</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhSortableRoot</code></td><td><code>default</code></td><td><code>SortableRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSortableItem</code></td><td><code>itemId</code></td><td><code>string</code></td><td>是</td><td>项标识，与 ids 中的值一一对应。</td></tr><tr><td><code>XhSortableItem</code></td><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>单独禁用该项。整份 disabled 在 Root 上，该项是项级的。</td></tr><tr><td><code>XhSortableItem</code></td><td><code>children</code></td><td><code>SlotChildren&lt;SortableItemSlotProps&gt;</code></td><td></td><td></td></tr><tr><td><code>XhSortableItemDragTrigger</code></td><td><code>itemId</code></td><td><code>string</code></td><td>是</td><td>项标识，与 ids 中的值一一对应。</td></tr><tr><td><code>XhSortableItemDragTrigger</code></td><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>单独禁用该项。整份 disabled 在 Root 上，该项是项级的。</td></tr><tr><td><code>XhSortableRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;SortableRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>pending</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>ITEM.POINTER_DOWN</code> · <code>POINTER.MOVE</code> · <code>POINTER.END</code> · <code>POINTER.CANCEL</code> · <code>ITEM.PICKUP</code> · <code>KEY.MOVE</code> · <code>KEY.DROP</code> · <code>KEY.CANCEL</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canSort</code> · <code>passedActivation</code> · <code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>正在拖（含键盘拖动）。</td></tr><tr><td><code>activeId</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>from</code></td><td><code>number</code></td><td></td></tr><tr><td><code>to</code></td><td><code>number</code></td><td></td></tr><tr><td><code>mode</code></td><td><code>SortableMode | null</code></td><td></td></tr><tr><td><code>items</code></td><td><code>SortableItemState[]</code></td><td>逐项的呈现状态，顺序与 <code>ids</code> 一致。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: SortableItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemDragTriggerProps</code></td><td><code>(props: SortableItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDropIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>落点线：拖动中且落点与起点不同位时才存在，位置由内联样式给出。</td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/keyboard-interface/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in item-drag-trigger，未在拖动，not disabled</td><td>拾起这一项，进入键盘拖动；播报它现在第几位、共几项、以及接下来能按什么</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>键盘拖动中</td><td>往后挪一位并播报新位置；已在末位时不动，也不回绕。竖直排布认上下键、水平排布认左右键，另一条轴上的方向键原样放行</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>键盘拖动中</td><td>往前挪一位，规则同上；rtl 下左右两键对调，语义恒是「往前 / 往后」</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>键盘拖动中</td><td>放下，按当前位置提交顺序并播报落点</td></tr><tr><td><code>Escape</code></td><td>键盘拖动中</td><td>取消，顺序回到拾起前，播报已取消与原位置</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>held on item-drag-trigger, not disabled</td><td>按住期间把手投影 data-pressed，与指针 :active 同一副按压面；拾起转拖动那一下即撤下（拖动中的回执是 data-dragging），抬起或失焦撤下</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>translations?.root</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>aria-label</code></td><td>translations?.itemDragTrigger?.(name)</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>aria-pressed</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>aria-roledescription</code></td><td>&#39;sortable&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>role</code></td><td>&#39;button&#39;</td></tr><tr><td><code>drop-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><ul><li>空格拾取或放下，方向键移动，Escape 取消。</li><li><code>live-region</code> 会播报当前拖动位置。</li><li>拖动期间焦点保留在当前手柄。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/sortable.css</code> 使用 <code>[data-scope=&quot;sortable&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-animating</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>String(item?.index ?? -1)</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-xh-action-profile</code></td><td>&#39;icon&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>item-drag-trigger</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>drop-indicator</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-sortable-drag-bg-active</code></td><td><code>item-drag-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-bg-pressed</code></td><td>sortable 的 item-drag-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-bg-hover</code></td><td><code>item-drag-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-_action-variant-bg-hover</code></td><td>sortable 的 item-drag-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-fg</code></td><td><code>item-drag-trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>sortable 的 item-drag-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-fg-disabled</code></td><td><code>item-drag-trigger</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-disabled</code></td><td>sortable 的 item-drag-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-fg-hover</code></td><td><code>item-drag-trigger</code></td><td><code>color</code></td><td><code>disabled</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-fg-default</code></td><td>sortable 的 item-drag-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-grip-h</code></td><td><code>item-drag-trigger</code></td><td><code>block-size</code></td><td><code>empty</code></td><td><code>--xh-space-3</code></td><td>sortable 的 item-drag-trigger 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-grip-w</code></td><td><code>item-drag-trigger</code></td><td><code>inline-size</code></td><td><code>empty</code></td><td><code>--xh-space-1</code></td><td>sortable 的 item-drag-trigger 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-icon-size</code></td><td><code>item-drag-trigger</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-glyph-size</code></td><td>sortable 的 item-drag-trigger 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-radius</code></td><td><code>item-drag-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>sortable 的 item-drag-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drag-size</code></td><td><code>item-drag-trigger</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>min-inline-size</code></td><td><code>default</code><br><code>xh-action-profile=icon</code></td><td><code>--xh-_action-profile-visual-size</code></td><td>sortable 的 item-drag-trigger 部件 block-size、inline-size、min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drop-indicator-bg</code></td><td><code>drop-indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-brand</code></td><td>sortable 的 drop-indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drop-indicator-radius</code></td><td><code>drop-indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>sortable 的 drop-indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-sortable-drop-indicator-size</code></td><td><code>drop-indicator</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>orientation=both</code><br><code>orientation=horizontal</code><br><code>orientation=vertical</code></td><td><code>--xh-stroke-thick</code></td><td>sortable 的 drop-indicator 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-sortable-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>sortable 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-sortable-item-opacity-dragging</code></td><td><code>item</code></td><td><code>opacity</code></td><td><code>dragging</code></td><td><code>0.9</code></td><td>sortable 的 item 部件 opacity 覆盖槽。</td></tr><tr><td><code>--xh-sortable-item-shadow-dragging</code></td><td><code>item</code></td><td><code>box-shadow</code></td><td><code>dragging</code></td><td><code>--xh-elevation-lifted</code></td><td>sortable 的 item 部件 box-shadow 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态 · 切换（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>box-shadow</code> · <code>opacity</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：值由内核逐帧算出（<code>frameLoop</code>），皮肤里看不到这段。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>pointer: coarse</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p>',61))])}const S=c(s,[["render",h]]);export{f as __pageData,S as default};
